export default function ForbiddenPage() {
  return (
    <main style={{
      padding: '2rem',
      fontFamily: 'system-ui, sans-serif',
      textAlign: 'center',
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center'
    }}>
      <div style={{
        maxWidth: '600px',
        padding: '2rem',
        backgroundColor: '#fee',
        borderRadius: '12px',
        border: '2px solid #c33'
      }}>
        <h1 style={{
          fontSize: '4rem',
          margin: '0',
          color: '#c33'
        }}>403</h1>
        <h2 style={{
          fontSize: '1.5rem',
          margin: '1rem 0',
          color: '#333'
        }}>Access Forbidden</h2>
        <p style={{
          fontSize: '1rem',
          color: '#666',
          lineHeight: '1.6'
        }}>
          You do not have permission to access this page.
          This area is restricted to users with admin privileges.
        </p>
        <a
          href="/"
          style={{
            display: 'inline-block',
            marginTop: '1.5rem',
            padding: '0.75rem 1.5rem',
            backgroundColor: '#333',
            color: 'white',
            textDecoration: 'none',
            borderRadius: '6px',
            fontWeight: '500'
          }}
        >
          Return to Home
        </a>
      </div>
    </main>
  );
}

